//go:build amd64

package floats

// maxAbsMulAVX2 is generated by maxabsmul_amd64_gen.go into maxabsmul_amd64.s:
// VANDPD+VMULPD, then VMAXPD with the product as first operand (a NaN product
// returns the accumulator). w has been sliced to len(v).
//
//go:noescape
func maxAbsMulAVX2(v, w []float64) float64

func maxAbsMul(v, w []float64) float64 {
	if hasAVX2FMA {
		return maxAbsMulAVX2(v, w)
	}
	return maxAbsMulRef(v, w)
}
